 const finishSwitch=(keep:boolean)=>{if(r){onKeep(r.id,keep?latest.current||undefined:undefined)}onDirty(false);setPending(null);pending?.();setEpoch(v=>v+1)};
 const ready=records.filter(v=>v.state==='allocation').length;
 return <div className="visual-planner">
  <div className="section-heading" data-testid="workspace-heading"><div><h2 className="text-section-title">Build a clear plan for every trip</h2><p>Start with a request. Choose the time, vehicle and people. Check the whole plan before saving.</p></div><Button variant="outline" onClick={()=>change(onCalendar)}><CalendarDays/>View transport calendar</Button></div>
  <SectionTabs id="planner-sections" label="Planner request filter" value={queue} onChange={id=>change(()=>{setQueue(id);setSuccess('');onSelect('')})} tabs={[{key:'all',label:'All',icon:ClipboardCheck,count:records.length},{key:'ready',label:'Ready',icon:CheckCircle2,count:ready},{key:'planned',label:'Planned',icon:CalendarDays,count:records.filter(r=>!!r.booking).length}]}/>
  <div className="pb-workspace"><aside className="pb-queue" aria-label="Transport requests to plan"><div className="pb-queue-title"><h3>Choose a request</h3><span>{records.length}</span></div><p className="muted">{ready} ready to plan · {records.filter(v=>['assessment','information'].includes(v.state)).length} need a response</p>
   {visible.length?visible.map(v=><button className={'pb-request '+(r?.id===v.id?'chosen':'')} key={v.id} aria-pressed={r?.id===v.id} onClick={()=>switchRecord(v.id)}><div><strong>{v.person}</strong><time>{time(v.start)}</time></div><span>{v.destination}</span><small>{v.state==='allocation'?'Ready to plan':v.state==='assessment'?'Assessment needed':v.state==='information'?'Waiting for information':bookingLabel(v.booking!)}{drafts[v.id]?' · Draft kept':''}</small><span className="pb-request-ref">{v.id}<ChevronRight/></span></button>):<p className="pb-queue-empty">No matching requests. Change the search or filter.</p>}
   <div className="pb-queue-help"><ShieldCheck/><p>Saved plans use the same bookings shown in Fleet.</p></div>
  </aside>
  {!r?<section className="pb-empty"><Route/><h2>No request selected</h2><p>Choose a different site, date or search to see transport requests.</p></section>:<section className="pb-editor" aria-label="Transport plan builder"><div className="pb-record-heading"><div><span className="eyebrow">{r.id} · {siteNames[r.site]}</span><h2>{r.person}</h2><p>{r.purpose}</p></div><Button variant="ghost" onClick={()=>change(()=>props.onOpen(r))}><FileText/>Open {r.booking?'booking':'request'}</Button></div>
    {success===r.id?<SavedPlan r={r} onEdit={()=>{setSuccess('');setEpoch(v=>v+1)}} onCalendar={onCalendar} onOpen={()=>props.onOpen(r)} onNext={()=>{const next=sorted.find(v=>v.state==='allocation'&&v.id!==r.id);setSuccess('');onSelect(next?.id||r.id)}}/>:['assessment','information'].includes(r.state)?<section className="pb-prerequisite"><div className="pb-callout-icon"><ClipboardCheck/></div><h3>{r.state==='assessment'?'Confirm the transport need first':'Some details are still needed'}</h3><p>{r.state==='assessment'?'Review the passenger’s practical transport needs before choosing a vehicle and team.':r.need}</p><div className="pb-need-tags"><span><Users/>{r.seats} people including driver</span>{r.wheelchair&&<span><Accessibility/>Wheelchair position</span>}{r.escortRequired&&<span><Users/>Escort required</span>}</div><div className="pb-next-owner"><strong>Next person</strong><span>{r.state==='assessment'?r.owner:r.requester}</span></div>{load==='ready'&&(role==='allocator'||r.state==='information'&&role==='requester')?<Button onClick={()=>props.onAction(r.state==='assessment'?'assess':'respond',r)}>{r.state==='assessment'?'Review transport needs':'Add missing information'}<ArrowRight/></Button>:<p className="muted">Waiting for the named person to resolve this request.</p>}</section>:<PlanEditor key={r.id+'-'+r.version+'-'+epoch+'-'+role+'-'+load} r={r} {...props} onDraft={v=>{latest.current=v;props.onSnapshot(r.id,v)}} kept={drafts[r.id]} onKeepPlan={v=>{onKeep(r.id,v);onDirty(false)}} onDiscard={()=>{onKeep(r.id,undefined);onDirty(false);setEpoch(v=>v+1)}} onComplete={message=>{onDirty(false);onKeep(r.id,undefined);onSelect(r.id);setSuccess(r.id);props.onSaved(message,latest.current?.plan.start.slice(0,10))}}/>}
  </section>}
  </div>
  {pending&&<Modal open title="Keep this plan before switching?" description="Nothing has been sent for a booking decision." onClose={()=>setPending(null)} footer={<><Button variant="outline" onClick={()=>setPending(null)}>Keep editing</Button><Button variant="outline" onClick={()=>finishSwitch(false)}>Discard and continue</Button><Button onClick={()=>finishSwitch(true)}>Keep draft and continue</Button></>}>Your draft can stay in this preview while you inspect another request or the calendar. It is cleared when the preview reloads.</Modal>}
 </div>;
