 const stageNav=useRef<HTMLElement>(null);const operation=useRef(crypto.randomUUID()),request=useRef(0);const mutable=role==='allocator'&&load==='ready',dirty=JSON.stringify(p)!==baseline,fingerprint=planFingerprint(r,p,allRecords,availability),currentCheck=checked===fingerprint&&availability==='available';
