 const setStage=(next:number)=>{setError('');if(next>0&&planIssues(r,p,[], 'available').some(v=>v.area==='time')){setError('Choose a valid departure and a later expected return.');return}if(next===2){const missing=planIssues(r,p,[], 'available');if(missing.length){setError(missing.map(v=>v.message).join(' '));return}}setStep(next);requestAnimationFrame(()=>{stageNav.current?.scrollIntoView({block:'start'});stageNav.current?.querySelector<HTMLButtonElement>('[aria-current=step]')?.focus({preventScroll:true})})};
 const check=()=>{const ticket=++request.current;setChecking(true);setChecked('');setReview(null);setError('');window.setTimeout(()=>{if(ticket!==request.current)return;const issues=planIssues(r,p,allRecords,availability);setReview(issues);if(!issues.length)setChecked(fingerprint);setChecking(false)},200)};
 const save=()=>{try{if(!currentCheck)throw Error('Check this exact plan before saving.');onComplete(onCommit({id:operation.current,record:r.id,type:r.booking?'reschedule':'allocate',version:r.version,payload:{...p,planCheck:fingerprint}}))}catch(e){setError((e as Error).message)}};
