/* ---- date helpers ------------------------------------------------------- */

export const pad = (n: number): string => String(n).padStart(2, '0');
export const sameDay = (a: Date, b: Date): boolean =>
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate();
export const addDays = (d: Date, n: number): Date => {
    const r = new Date(d);
    r.setDate(r.getDate() + n);
    return r;
};
export const startOfWeek = (d: Date): Date => {
    const r = new Date(d);
    r.setHours(0, 0, 0, 0);
    r.setDate(r.getDate() - r.getDay());
    return r;
};
export const startOfMonth = (d: Date): Date =>
    new Date(d.getFullYear(), d.getMonth(), 1);
export const endOfMonth = (d: Date): Date =>
    new Date(d.getFullYear(), d.getMonth() + 1, 0);
export const minutes = (d: Date): number => d.getHours() * 60 + d.getMinutes();
export function fmtTime(d: Date): string {
    let h = d.getHours();
    const m = d.getMinutes();
    const ap = h >= 12 ? 'pm' : 'am';
    h = h % 12 || 12;
    return m ? `${h}:${pad(m)}${ap}` : `${h}${ap}`;
}
export const fmtTimeRange = (s: Date, e: Date | null): string =>
    e ? `${fmtTime(s)} – ${fmtTime(e)}` : fmtTime(s);

