/**
 * Compact month grid for the "jump to date" picker in the banner/toolbar — lets the
 * user navigate to any day directly instead of stepping period-by-period. Pure grid;
 * the Popover wrapper lives in SiteCalendar (it owns periodLabel + the trigger style).
 */
export function MiniMonth({
    selected,
    onSelect,
}: {
    selected: Date;
    onSelect: (d: Date) => void;
}) {
    const [cursor, setCursor] = useState(() => startOfMonth(selected));
    const today = new Date();
    const gridStart = startOfWeek(startOfMonth(cursor));
    const days = Array.from({ length: 42 }, (_, i) => addDays(gridStart, i));
    const shiftMonth = (delta: number) =>
        setCursor((c) => new Date(c.getFullYear(), c.getMonth() + delta, 1));

    return (
        <div className="w-60 p-1">
            <div className="mb-1 flex items-center justify-between px-1">
                <GuardrailButton
                    unstyled
                    type="button"
                    onClick={() => shiftMonth(-1)}
                    aria-label="Previous month"
                    className="inline-flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-muted"
                >
                    <ChevronLeft className="h-4 w-4" />
                </GuardrailButton>
                <span className="text-sm font-semibold">
                    {MO[cursor.getMonth()]} {cursor.getFullYear()}
                </span>
                <GuardrailButton
                    unstyled
                    type="button"
                    onClick={() => shiftMonth(1)}
                    aria-label="Next month"
                    className="inline-flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-muted"
                >
                    <ChevronRight className="h-4 w-4" />
                </GuardrailButton>
            </div>
            <div className="grid grid-cols-7 gap-0.5 px-1 text-center text-[10px] font-medium text-muted-foreground uppercase">
                {WD.map((d) => (
                    <div key={d}>{d.slice(0, 2)}</div>
                ))}
            </div>
            <div className="grid grid-cols-7 gap-0.5 p-1">
                {days.map((d) => {
                    const inMonth = d.getMonth() === cursor.getMonth();
                    const isToday = sameDay(d, today);
                    const isSelected = sameDay(d, selected);
                    const tone = isSelected
                        ? 'bg-primary font-semibold text-primary-foreground'
                        : isToday
                          ? 'font-semibold text-primary ring-1 ring-primary/40 hover:bg-muted'
                          : inMonth
                            ? 'text-foreground hover:bg-muted'
                            : 'text-muted-foreground/40 hover:bg-muted';
                    return (
                        <GuardrailButton
                            unstyled
                            key={d.toISOString()}
                            type="button"
                            onClick={() => onSelect(d)}
                            aria-current={isToday ? 'date' : undefined}
                            aria-label={`${WD_FULL[d.getDay()]} ${d.getDate()} ${MO[d.getMonth()]} ${d.getFullYear()}`}
                            className={`inline-flex h-8 items-center justify-center rounded-md text-xs transition-colors ${tone}`}
                        >
                            {d.getDate()}
                        </GuardrailButton>
                    );
                })}
            </div>
        </div>
    );
}

/* ---- period label + jump to date (Site Calendar filter row) ------------- */

export type CalView = 'month' | 'week' | 'day' | 'agenda' | 'timeline';

export function viewRange(
    view: CalView,
    navDate: Date,
): { start: Date; end: Date } {
    if (view === 'week') {
        const s = startOfWeek(navDate);
        return { start: s, end: addDays(s, 7) };
    }
    if (view === 'day') {
        const s = new Date(navDate);
        s.setHours(0, 0, 0, 0);
        return { start: s, end: addDays(s, 1) };
    }
    const s = startOfWeek(startOfMonth(navDate));
    return { start: s, end: addDays(s, 42) };
}

/** The browsed period; a week across December/January names both years. */
export function periodLabel(view: CalView, navDate: Date): string {
    if (view === 'day') {
        return navDate.toLocaleDateString('en-NZ', {
            weekday: 'short',
            day: 'numeric',
            month: 'long',
            year: 'numeric',
        });
    }
    if (view === 'week') {
        const s = startOfWeek(navDate);
        const e = addDays(s, 6);
        const startYear =
            s.getFullYear() !== e.getFullYear() ? ` ${s.getFullYear()}` : '';
        return `${s.getDate()} ${MO[s.getMonth()].slice(0, 3)}${startYear} – ${e.getDate()} ${MO[e.getMonth()].slice(0, 3)} ${e.getFullYear()}`;
    }
    return `${MO[navDate.getMonth()]} ${navDate.getFullYear()}`;
}

/**
 * Clickable period label that opens a mini-month so the user can jump straight to any
 * date instead of stepping period-by-period. `pill` renders it as an Event Horizon
 * filter-row field; the light variant is used by the profile-embed toolbar.
 */
export function JumpToDate({
    view,
    navDate,
    onPick,
    pill = false,
}: {
    view: CalView;
    navDate: Date;
    onPick: (d: Date) => void;
    pill?: boolean;
}) {
    const [open, setOpen] = useState(false);

    return (
        <Popover open={open} onOpenChange={setOpen}>
            <PopoverTrigger asChild>
                {pill ? (
                    <PageHeaderFilterButton
                        icon={CalendarDays}
                        aria-label="Jump to date"
                        className="tnum"
                    >
                        {periodLabel(view, navDate)}
                        <ChevronDown className="size-3 opacity-70" />
                    </PageHeaderFilterButton>
                ) : (
                    // eslint-disable-next-line no-restricted-syntax -- calendar jump trigger; not a shadcn Button.
                    <button
                        type="button"
                        aria-label="Jump to date"
                        className="tnum inline-flex min-w-[150px] items-center gap-1.5 rounded-md px-2 py-1 text-sm font-semibold transition-colors hover:bg-muted"
                    >
                        <CalendarDays className="h-3.5 w-3.5" />
                        {periodLabel(view, navDate)}
                        <ChevronDown className="h-3 w-3 opacity-70" />
                    </button>
                )}
            </PopoverTrigger>
            <PopoverContent
                align={pill ? 'end' : 'start'}
                className="w-auto p-0"
            >
                <MiniMonth
                    selected={navDate}
                    onSelect={(d) => {
                        onPick(d);
                        setOpen(false);
                    }}
                />
            </PopoverContent>
        </Popover>
    );
}

