const GRID_START = 0;
const GRID_END = 24;
const HOUR_H = 54;
const HOURS = Array.from(
    { length: GRID_END - GRID_START },
    (_, i) => GRID_START + i,
);
const topFor = (min: number): number => ((min - GRID_START * 60) / 60) * HOUR_H;

/** One tab stop per day; arrow keys reach the other hours without 168 tab stops. */
export function CalendarTimeSlot({ day, hour }: { day: Date; hour: number }) {
    const { onCreateAt, onContext } = useCalUI();
    if (!onCreateAt)
        return (
            <div
                className="border-b border-border/60"
                style={{ height: HOUR_H }}
            />
        );
    const time = new Date(day);
    time.setHours(hour, 0, 0, 0);
    return (
        <GuardrailButton unstyled
            type="button"
            data-calendar-slot
            tabIndex={hour === 9 ? 0 : -1}
            aria-label={`Create entry on ${time.toLocaleString('en-NZ', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', hour: 'numeric', minute: '2-digit' })}`}
            className="block w-full border-b border-border/60 text-left hover:bg-primary/5 focus-visible:relative focus-visible:z-10 focus-visible:bg-primary/10 focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
            style={{ height: HOUR_H }}
            onClick={() => onCreateAt(day, hour)}
            // The slot knows its own hour, so Shift+F10 on a focused slot
            // (which reports no pointer position) still opens that hour.
            onContextMenu={
                onContext
                    ? (e) => {
                          e.preventDefault();
                          e.stopPropagation();
                          onContext(e, day, hour);
                      }
                    : undefined
            }
            onKeyDown={(e) => {
                if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(e.key))
                    return;
                e.preventDefault();
                const slots = Array.from(
                    e.currentTarget.parentElement?.querySelectorAll<HTMLButtonElement>(
                        '[data-calendar-slot]',
                    ) ?? [],
                );
                const index = slots.indexOf(e.currentTarget);
                slots[
                    e.key === 'Home'
                        ? 0
                        : e.key === 'End'
                          ? slots.length - 1
                          : Math.max(
                                0,
                                Math.min(
                                    slots.length - 1,
                                    index + (e.key === 'ArrowDown' ? 1 : -1),
                                ),
                            )
                ]?.focus();
            }}
        />
    );
}

/** Scroll a time-grid to ~6am on mount / period change so the working day is in
 *  view even though the grid now spans the full 24 hours (midnight → midnight). */
function useGridAutoScroll(navDate: Date) {
    const ref = useRef<HTMLDivElement | null>(null);
    useEffect(() => {
        if (ref.current) ref.current.scrollTop = topFor(6 * 60);
    }, [navDate]);
    return ref;
}

/** Width (px) the vertical scrollbar steals from a scroll container, so the
 *  fixed day-header / all-day rows can reserve the same gutter and keep their
 *  columns aligned with the scrolling time grid below. 0 with overlay scrollbars. */
function useScrollbarWidth(ref: { current: HTMLDivElement | null }): number {
    const [w, setW] = useState(0);
    useEffect(() => {
        const el = ref.current;
        if (!el) return;
        const measure = () => setW(el.offsetWidth - el.clientWidth);
        measure();
        const ro = new ResizeObserver(measure);
        ro.observe(el);
        return () => ro.disconnect();
    }, [ref]);
    return w;
}

type Packed = Decorated & {
    _s: number;
    _e: number;
    _col: number;
    _cols: number;
};

export function occursOnDay(entry: Decorated, day: Date): boolean {
    const start = new Date(day); start.setHours(0, 0, 0, 0);
    const end = new Date(start); end.setDate(end.getDate() + 1);
    return entry._start < end && (entry._end && entry._end > entry._start ? entry._end > start : entry._start >= start);
}

export function packDay(list: Decorated[], day: Date): Packed[] {
    const evs = list
        .filter((e) => !e.allDay)
        .map((e) => ({ ...e, _s: 0, _e: 0, _col: 0, _cols: 1 }) as Packed)
        .sort((a, b) => a._start.getTime() - b._start.getTime());
    const out: Packed[] = [];
    let cluster: Packed[] = [];
    let clusterEnd = -1;
    const flush = () => {
        const cols: number[] = [];
        cluster.forEach((e) => {
            let placed = false;
            for (let c = 0; c < cols.length; c++) {
                if (cols[c] <= e._s) {
                    e._col = c;
                    cols[c] = e._e;
                    placed = true;
                    break;
                }
            }
            if (!placed) {
                e._col = cols.length;
                cols.push(e._e);
            }
        });
        cluster.forEach((e) => {
            e._cols = cols.length;
            out.push(e);
        });
        cluster = [];
        clusterEnd = -1;
    };
    evs.forEach((e) => {
        const boundary = new Date(day); boundary.setHours(0, 0, 0, 0);
        const next = new Date(boundary); next.setDate(next.getDate() + 1);
        const s = e._start < boundary ? 0 : minutes(e._start);
        const en = e._end ? (e._end >= next ? 1440 : minutes(e._end)) : Math.min(s + 45, 1440);
        e._s = s;
        e._e = en;
        if (cluster.length && s >= clusterEnd) flush();
        cluster.push(e);
        clusterEnd = Math.max(clusterEnd, en);
    });
    flush();
    return out;
}

function TimeBlock({ ev, compact }: { ev: Packed; compact?: boolean }) {
    const ui = useCalUI();
    const { colorBy, srcByKey, onSelect, onMove, onPreview, onPreviewEnd } =
        ui;
    const top = topFor(ev._s);
    const canDrag =
        !!onMove &&
        ev.editable &&
        !ev.allDay &&
        !ev.recurrence &&
        !ev.isOccurrence;
    const touch = useRef(false);
    const dragCleanup = useRef<(() => void) | null>(null);
    useEffect(() => () => dragCleanup.current?.(), []);
    const baseH = Math.max(((ev._e - ev._s) / 60) * HOUR_H - 3, 22);
    const [drag, setDrag] = useState<{
        mode: 'move' | 'resize';
        dy: number;
    } | null>(null);
    const overdue = ev.status === 'overdue';

    const startDrag = (mode: 'move' | 'resize') => (e: React.PointerEvent) => {
        touch.current = e.pointerType === 'touch';
        // Let touch scrolling remain native. Tap opens the same date/time editor.
        if (touch.current) return;
        if (e.button !== 0) return;
        onPreviewEnd?.();
        if (!canDrag || !onMove) {
            if (mode === 'move') onSelect(ev);
            return;
        }
        e.preventDefault();
        e.stopPropagation();
        const startY = e.clientY;
        let dy = 0;
        let moved = false;
        const cleanup = () => {
            window.removeEventListener('pointermove', move);
            window.removeEventListener('pointerup', up);
            window.removeEventListener('pointercancel', cancel);
            dragCleanup.current = null;
        };
        const cancel = () => {
            cleanup();
            setDrag(null);
        };
        const move = (me: PointerEvent) => {
            dy = me.clientY - startY;
            if (Math.abs(dy) > 3) moved = true;
            setDrag({ mode, dy });
        };
        const up = () => {
            cleanup();
            setDrag(null);
            const snap = Math.round(((dy / HOUR_H) * 60) / 15) * 15;
            if (moved && snap !== 0) {
                const s = new Date(ev._start);
                const e2 = ev._end
                    ? new Date(ev._end)
                    : new Date(s.getTime() + 45 * 60000);
                if (mode === 'move') {
                    s.setMinutes(s.getMinutes() + snap);
                    e2.setMinutes(e2.getMinutes() + snap);
                } else {
                    e2.setMinutes(e2.getMinutes() + snap);
                    if (e2 <= s) e2.setTime(s.getTime() + 15 * 60000);
                }
                onMove(ev, s, e2);
            } else if (!moved) {
                onSelect(ev);
            }
        };
        window.addEventListener('pointermove', move);
        window.addEventListener('pointerup', up);
        window.addEventListener('pointercancel', cancel);
        dragCleanup.current = cleanup;
    };

    const dy = drag ? drag.dy : 0;
    const liveTop = top + (drag && drag.mode === 'move' ? dy : 0);
    const liveH = Math.max(
        baseH + (drag && drag.mode === 'resize' ? dy : 0),
        22,
    );
    const w = 100 / ev._cols;
    const srcLbl = srcByKey[ev.source]?.label ?? ev.source;
    const ariaLabel = `${ev.title}, ${ev.allDay ? 'all day' : fmtTimeRange(ev._start, ev._end)}, ${srcLbl}`;
    return (
        <div
            role="button"
            tabIndex={0}
            aria-label={ariaLabel}
            onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    onPreviewEnd?.();
                    onSelect(ev);
                }
            }}
            onPointerDown={startDrag('move')}
            onClick={() => {
                if (touch.current) onSelect(ev);
            }}
            onContextMenu={(e) => contextEntry(e, ev, ui)}
            onMouseEnter={(e) => {
                if (!drag) onPreview?.(ev, e.currentTarget);
            }}
            onMouseLeave={() => onPreviewEnd?.()}
            style={{
                ...cv(ev, colorBy),
                top: liveTop,
                height: liveH,
                left: `calc(${ev._col * w}% + 2px)`,
                width: `calc(${w}% - 4px)`,
                background: 'var(--cb)',
                borderColor: 'var(--cl)',
                boxShadow: 'inset 3px 0 0 var(--c)',
                zIndex: drag ? 30 : undefined,
            }}
            className={`absolute overflow-hidden rounded-md border px-2 py-1 text-left transition-shadow select-none hover:z-10 hover:shadow-md focus-visible:z-10 focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none ${canDrag ? 'cursor-grab active:cursor-grabbing' : 'cursor-pointer'} ${drag ? 'shadow-lg ring-1 ring-primary/40' : ''}`}
        >
            <div
                className="flex items-center gap-1"
                style={{ color: 'var(--c)' }}
            >
                <SourceIcon k={ev.source} className="h-3 w-3 shrink-0" />
                <span className="tnum truncate text-[10px] font-semibold">
                    {fmtTime(ev._start)}
                </span>
                <RecurGlyph
                    ev={ev}
                    className="ml-auto h-2.5 w-2.5 shrink-0 opacity-60"
                />
            </div>
            <div
                className={`truncate text-[12px] leading-tight font-medium text-foreground ${compact ? '' : 'mt-0.5'}`}
            >
                {ev.title}
            </div>
            {!compact && liveH > 52 && ev.room && (
                <div className="mt-0.5 flex items-center gap-1 text-[10.5px] text-muted-foreground">
                    <MapPin className="h-2.5 w-2.5" />
                    <span className="truncate">{ev.room}</span>
                </div>
            )}
            {overdue && (
                <span
                    aria-hidden="true"
                    className="absolute top-1 right-1 h-1.5 w-1.5 rounded-full bg-status-critical"
                />
            )}
            {canDrag && (
                <div
                    aria-hidden="true"
                    onPointerDown={startDrag('resize')}
                    className="absolute inset-x-0 bottom-0 h-2 cursor-ns-resize"
                    title="Drag to resize"
                />
            )}
        </div>
    );
}

