export const formTitles:Record<string,string>={request:'Request transport',assess:'Assess transport need',information:'Request more information',respond:'Provide missing information',allocate:'Allocate transport',reschedule:'Change resources or time',approve:'Review booking approval',reject:'Reject booking',check:'Vehicle pre-use check',checkout:'Collect keys and equipment',depart:'Record actual departure',return:'Record actual return',custody:'Receive outstanding items',passengers:'Confirm passenger return',medication:'Medication logistics source',complete:'Complete journey',cancel:'Record a demand outcome',handover:'Hand over to another shift',accept:'Acknowledge handover',dispute:'Dispute handover',exception:'Assign an exception',resolve:'Record reconciliation',note:'Add a record note',evidence:'Add supporting evidence'};
